// Optional WebRTC data-only co-op. Signaling is exchanged by the players.
export class PeerSquad {
 constructor({status,onReady,onMessage,onClose}){Object.assign(this,{status,onReady,onMessage,onClose});this.pc=null;this.channel=null;this.role=null;this.connected=false;}
 close(notify=false){this.connected=false;const pc=this.pc,ch=this.channel;this.pc=null;this.channel=null;if(ch){ch.onopen=ch.onclose=ch.onmessage=null;ch.close();}pc?.close();if(notify)this.onClose?.();}
 setup(role){this.close();this.role=role;const pc=this.pc=new RTCPeerConnection({iceServers:[{urls:'stun:stun.l.google.com:19302'}]});pc.onconnectionstatechange=()=>{if(this.pc!==pc)return;this.status('Connection: '+pc.connectionState);if(['failed','disconnected','closed'].includes(pc.connectionState)){this.connected=false;this.onClose?.();}};pc.ondatachannel=e=>{if(this.pc!==pc){e.channel.close();return;}this.bind(e.channel);};return pc;}
 bind(channel){this.channel=channel;channel.onopen=()=>{if(this.channel!==channel)return;this.connected=true;this.status('Connected. Host can deploy the squad.');this.onReady?.(this.role);};channel.onclose=()=>{if(this.channel!==channel)return;this.connected=false;this.onClose?.();};channel.onmessage=e=>{if(this.channel!==channel)return;if(typeof e.data!=='string'||e.data.length>100000)return;try{const m=JSON.parse(e.data);if(m&&typeof m==='object'&&typeof m.type==='string')this.onMessage(m);}catch{}};}
 async gathered(pc){if(pc.iceGatheringState==='complete')return;await new Promise((resolve,reject)=>{const timer=setTimeout(()=>{pc.removeEventListener('icegatheringstatechange',check);if(pc.localDescription?.sdp?.includes('candidate:'))resolve();else reject(new Error('No connection candidates found. Try another browser or network.'));},12000);const check=()=>{if(pc.iceGatheringState==='complete'){clearTimeout(timer);pc.removeEventListener('icegatheringstatechange',check);resolve();}};pc.addEventListener('icegatheringstatechange',check);});}
 encode(d){return btoa(JSON.stringify({v:2,type:d.type,sdp:d.sdp}));}
 decode(text,type){if(typeof text!=='string'||text.trim().length>50000)throw new Error('Connection code is too large.');let d;try{d=JSON.parse(atob(text.trim()));}catch{throw new Error('That is not a valid connection code.');}if(d.v!==2||d.type!==type||typeof d.sdp!=='string'||!d.sdp.startsWith('v=0'))throw new Error('Wrong connection code. Use the matching offer or answer from DUSTLINE.');return {type:d.type,sdp:d.sdp};}
 async host(){this.status('Preparing host code…');const pc=this.setup('host');this.bind(pc.createDataChannel('dustline',{ordered:true}));await pc.setLocalDescription(await pc.createOffer());await this.gathered(pc);if(this.pc!==pc)throw new Error('Connection setup cancelled.');this.status('Send your host code to your teammate, then paste their answer.');return this.encode(pc.localDescription);}
 async join(code){const d=this.decode(code,'offer');this.status('Preparing answer…');const pc=this.setup('guest');await pc.setRemoteDescription(d);await pc.setLocalDescription(await pc.createAnswer());await this.gathered(pc);if(this.pc!==pc)throw new Error('Connection setup cancelled.');this.status('Send this answer to the host. Keep this page open.');return this.encode(pc.localDescription);}
 async accept(code){if(!this.pc||this.role!=='host'||this.pc.signalingState!=='have-local-offer')throw new Error('Create a host code first.');await this.pc.setRemoteDescription(this.decode(code,'answer'));this.status('Connecting… If this takes over 30 seconds, try another network.');}
 send(message){if(!this.connected||this.channel?.readyState!=='open'||this.channel.bufferedAmount>200000)return false;this.channel.send(JSON.stringify(message));return true;}
}
